package com.vandorlabs.neoforge.copier;

import com.vandorlabs.copier.core.MaterialWithdrawal;
import com.vandorlabs.neoforge.transfer.*;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.nbt.*;
import net.minecraft.server.level.*;
import net.minecraft.world.*;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.block.ChestBlock;
import net.minecraft.world.level.block.entity.ChestBlockEntity;
import net.minecraft.world.level.block.entity.TrappedChestBlockEntity;
import net.minecraft.world.level.block.state.properties.*;

/** Physical vanilla chest slots, exact before/after images and callback-safe incremental withdrawal. */
public final class NativeCopySupply {
    private static final int MAX_BYTES=1024*1024;
    private record Chest(NativeRawCell before,NativeRawCell after,List<ItemStack> oldItems,List<ItemStack> nextItems){}
    private final List<Chest> chests;
    private NativeCopySupply(List<Chest> chests){this.chests=List.copyOf(chests);}
    public List<BlockPos> positions(){return chests.stream().map(chest->chest.before.pos).toList();}
    public List<NativeRawCell> before(){return chests.stream().map(Chest::before).toList();}
    public List<NativeRawCell> after(){return chests.stream().map(Chest::after).toList();}
    public static NativeCopySupply prepare(ServerLevel level,ServerPlayer actor,BlockPos back,List<NativeCopyMaterials.Need> needs){
        thread(level);if(actor.serverLevel()!=level||!actor.isAlive()||actor.isSpectator())throw new IllegalArgumentException("Material actor unavailable");
        for(Direction side:Direction.values())loaded(level,back.relative(side));loaded(level,back);
        var state=level.getBlockState(back);if(!(state.getBlock() instanceof ChestBlock block)||!(level.getBlockEntity(back) instanceof ChestBlockEntity))throw new IllegalArgumentException("Place a material chest behind the Copy Controller");
        if(ChestBlock.getContainer(block,state,level,back,false)==null)throw new IllegalArgumentException("The material chest is obstructed");
        var positions=new ArrayList<BlockPos>();positions.add(back.immutable());
        if(state.getValue(BlockStateProperties.CHEST_TYPE)!=ChestType.SINGLE){var other=back.relative(ChestBlock.getConnectedDirection(state));loaded(level,other);var partner=level.getBlockState(other);if(!NativeCopyTiles.chestPartners(back,state,other,partner))throw new IllegalArgumentException("Complete the double material chest");positions.add(other.immutable());}
        positions.sort(BlockPos::compareTo);var staged=new ArrayList<ChestBlockEntity>();var images=new ArrayList<NativeRawCell>();var slots=new ArrayList<ItemStack>();
        for(var pos:positions){loaded(level,pos);if(!level.mayInteract(actor,pos)||!actor.mayUseItemAt(pos,Direction.UP,actor.getMainHandItem())||com.vandorlabs.neoforge.ramp.NativeRampHeldOwners.blocked(level,pos)||!(level.getBlockEntity(pos) instanceof ChestBlockEntity chest)||chest.getLootTable()!=null||!chest.canOpen(actor))throw new IllegalArgumentException("The material chest is locked, held or unavailable");
            var raw=chest.saveWithFullMetadata(level.registryAccess());var image=new NativeRawCell(pos,level.getBlockState(pos),raw,MAX_BYTES);var clone=(ChestBlockEntity)image.stage(level,NativeCopySupply::supported,CompoundTag::equals);images.add(image);staged.add(clone);for(int slot=0;slot<clone.getContainerSize();slot++)slots.add(clone.getItem(slot).copy());}
        long[] counts=new long[needs.size()];for(int n=0;n<counts.length;n++)counts[n]=needs.get(n).count;int[] available=new int[slots.size()];for(int i=0;i<slots.size();i++)available[i]=slots.get(i).getCount();
        final int[] remaining;try{remaining=MaterialWithdrawal.remaining(counts,available,(need,slot)->NativeCopyMaterials.satisfies(needs.get(need),slots.get(slot)));}catch(MaterialWithdrawal.Missing missing){throw new IllegalArgumentException("Missing material: "+needs.get(missing.need).item().getHoverName().getString()+" x "+missing.count);}
        var result=new ArrayList<Chest>();int cursor=0,bytes=0;for(int c=0;c<staged.size();c++){var clone=staged.get(c);var oldItems=new ArrayList<ItemStack>();var nextItems=NonNullList.withSize(clone.getContainerSize(),ItemStack.EMPTY);for(int slot=0;slot<clone.getContainerSize();slot++){var old=slots.get(cursor);oldItems.add(old.copy());nextItems.set(slot,old.copyWithCount(remaining[cursor++]));}var before=images.get(c);var next=before.tile();ContainerHelper.saveAllItems(next,nextItems,level.registryAccess());var after=new NativeRawCell(before.pos,before.state,next,MAX_BYTES);after.stage(level,NativeCopySupply::supported,CompoundTag::equals);bytes=Math.addExact(bytes,before.tile().sizeInBytes()+next.sizeInBytes());if(bytes>MAX_BYTES)throw new IllegalArgumentException("Material chest snapshot byte bound");result.add(new Chest(before,after,List.copyOf(oldItems),List.copyOf(nextItems)));}
        return new NativeCopySupply(result);
    }
    public CompoundTag write(){
        var result=new CompoundTag();result.putInt("Schema",1);var limits=new NativeTransferSnapshot.Limits(2,MAX_BYTES,MAX_BYTES*2,MAX_BYTES*8);result.put("Before",new NativeTransferSnapshot(before(),limits).write());result.put("After",new NativeTransferSnapshot(after(),limits).write());return result;
    }
    public static NativeCopySupply read(HolderLookup.Provider registries,CompoundTag input){
        if(!input.getAllKeys().equals(Set.of("Schema","Before","After"))||!input.contains("Schema",Tag.TAG_INT)||input.getInt("Schema")!=1||!input.contains("Before",Tag.TAG_COMPOUND)||!input.contains("After",Tag.TAG_COMPOUND))throw new IllegalArgumentException("Material receipt schema");var limits=new NativeTransferSnapshot.Limits(2,MAX_BYTES,MAX_BYTES*2,MAX_BYTES*8);var before=NativeTransferSnapshot.read(registries,input.getCompound("Before"),limits,state->Map.of());var after=NativeTransferSnapshot.read(registries,input.getCompound("After"),limits,state->Map.of());if(before.cells().size()!=after.cells().size())throw new IllegalArgumentException("Material receipt half count");var result=new ArrayList<Chest>();int bytes=0;for(int c=0;c<before.cells().size();c++){var old=before.cells().get(c);var next=after.cells().get(c);if(!old.pos.equals(next.pos)||old.state!=next.state||!(old.state.getBlock() instanceof ChestBlock))throw new IllegalArgumentException("Material receipt physical identity");var first=old.tile();var second=next.tile();if(first==null||second==null||first.contains("LootTable")||second.contains("LootTable"))throw new IllegalArgumentException("Material receipt tile identity");first.remove("Items");second.remove("Items");if(!first.equals(second))throw new IllegalArgumentException("Material receipt changed private chest metadata");var oldItems=readSlots(old.tile(),registries);var nextItems=readSlots(next.tile(),registries);for(int slot=0;slot<oldItems.size();slot++){var a=oldItems.get(slot);var b=nextItems.get(slot);if(!b.isEmpty()&&(a.isEmpty()||!ItemStack.isSameItemSameComponents(a,b)||b.getCount()>a.getCount()))throw new IllegalArgumentException("Material receipt invents or changes an item");}bytes=Math.addExact(bytes,old.tile().sizeInBytes()+next.tile().sizeInBytes());if(bytes>MAX_BYTES)throw new IllegalArgumentException("Material receipt byte bound");result.add(new Chest(old,next,oldItems,nextItems));}return new NativeCopySupply(result);
    }
    private static List<ItemStack> readSlots(CompoundTag raw,HolderLookup.Provider registries){
        if(!(raw.get("Items") instanceof ListTag list)||list.size()>27||!list.isEmpty()&&list.getElementType()!=Tag.TAG_COMPOUND)throw new IllegalArgumentException("Material chest item list");var result=NonNullList.withSize(27,ItemStack.EMPTY);boolean[] seen=new boolean[27];var budget=new com.vandorlabs.neoforge.inventory.NativeInventoryItems.Budget();for(Tag value:list){var entry=(CompoundTag)value;if(!entry.contains("Slot",Tag.TAG_BYTE))throw new IllegalArgumentException("Material chest slot type");int slot=entry.getByte("Slot")&255;if(slot>=27||seen[slot])throw new IllegalArgumentException("Material chest duplicate/out-of-range slot");seen[slot]=true;var item=entry.copy();item.remove("Slot");var stack=com.vandorlabs.neoforge.inventory.NativeInventoryItems.modern(item,registries,budget);if(stack.isEmpty()||stack.getCount()>Math.min(64,stack.getMaxStackSize()))throw new IllegalArgumentException("Material chest stack count");result.set(slot,stack.copy());}var canonical=new CompoundTag();ContainerHelper.saveAllItems(canonical,result,registries);if(!canonical.get("Items").equals(list))throw new IllegalArgumentException("Noncanonical material chest items");return List.copyOf(result);
    }
    boolean restoring(NativeRawCell target){for(var chest:chests)if(chest.before.pos.equals(target.pos)){if(target.identical(chest.before))return true;if(target.identical(chest.after))return false;throw new IllegalArgumentException("Unknown material publication value");}throw new IllegalArgumentException("Unknown material publication position");}
    void validateBacking(BlockPos back){if(chests.isEmpty()||chests.size()>2||!contains(back))throw new IllegalArgumentException("Material receipt is not behind this controller");for(var chest:chests){var state=chest.before.state;var type=state.getValue(BlockStateProperties.CHEST_TYPE);if(chests.size()==1){if(type!=ChestType.SINGLE)throw new IllegalArgumentException("Incomplete material chest receipt");}else{var partner=chests.get(chests.get(0)==chest?1:0);if(!NativeCopyTiles.chestPartners(chest.before.pos,state,partner.before.pos,partner.before.state))throw new IllegalArgumentException("Invalid paired material chest receipt");}}}
    public boolean contains(BlockPos pos){return chests.stream().anyMatch(chest->chest.before.pos.equals(pos));}
    public boolean recognizes(ServerLevel level,BlockPos pos){thread(level);for(var chest:chests)if(chest.before.pos.equals(pos)){known(level,chest);return true;}return false;}
    public void publishCell(ServerLevel level,NativeTransferHolds.Lease lease,BlockPos pos,boolean refund){thread(level);for(var chest:chests)if(chest.before.pos.equals(pos)){change(level,lease,chest,refund);if(!matches(level,refund?chest.before:chest.after))throw new IllegalStateException("Material cell publication changed private data");return;}throw new IllegalArgumentException("Material cell is outside its receipt");}
    public void validateCost(List<NativeCopyMaterials.Need> needs){var old=new ArrayList<ItemStack>();var next=new ArrayList<ItemStack>();for(var chest:chests){old.addAll(chest.oldItems);next.addAll(chest.nextItems);}long[] required=new long[needs.size()];int[] available=new int[old.size()];for(int i=0;i<required.length;i++)required[i]=needs.get(i).count;for(int i=0;i<available.length;i++)available[i]=old.get(i).getCount();int[] remaining=MaterialWithdrawal.remaining(required,available,(n,slot)->NativeCopyMaterials.satisfies(needs.get(n),old.get(slot)));for(int i=0;i<remaining.length;i++)if(!ItemStack.matches(old.get(i).copyWithCount(remaining[i]),next.get(i)))throw new IllegalArgumentException("Material receipt does not pay the exact construction cost");}
    public void validate(ServerLevel level){thread(level);for(var chest:chests)if(!matches(level,chest.before))throw new IllegalArgumentException("The material chest changed; try the copy again");}
    public void withdraw(ServerLevel level,NativeTransferHolds.Lease lease){validate(level);change(level,lease,false);for(var chest:chests)if(!matches(level,chest.after))throw new IllegalStateException("Material withdrawal callback changed the chest; recovery retained");}
    /** Each slot may only be one of this journal's two exact values. Unknown changes are never refunded over. */
    public void refund(ServerLevel level,NativeTransferHolds.Lease lease){change(level,lease,true);for(var chest:chests)if(!matches(level,chest.before))throw new IllegalStateException("Material refund callback changed the chest; recovery retained");}
    private void change(ServerLevel level,NativeTransferHolds.Lease lease,boolean refund){thread(level);for(var chest:chests)known(level,chest);for(var chest:chests)change(level,lease,chest,refund);}
    private static ChestBlockEntity known(ServerLevel level,Chest chest){var tile=physical(level,chest);var actual=tile.saveWithFullMetadata(level.registryAccess());var own=actual.copy();own.remove("Items");var expected=chest.before.tile();expected.remove("Items");if(!own.equals(expected))throw new IllegalStateException("Material chest metadata changed; recovery retained");for(int slot=0;slot<chest.oldItems.size();slot++){var current=tile.getItem(slot);if(!ItemStack.matches(current,chest.oldItems.get(slot))&&!ItemStack.matches(current,chest.nextItems.get(slot)))throw new IllegalStateException("Material chest slot changed; recovery retained");}return tile;}
    private static void change(ServerLevel level,NativeTransferHolds.Lease lease,Chest chest,boolean refund){var tile=known(level,chest);for(int slot=0;slot<chest.oldItems.size();slot++){var target=(refund?chest.oldItems:chest.nextItems).get(slot);if(!ItemStack.matches(tile.getItem(slot),target))lease.writeSlot(tile,slot,tile.getItem(slot).copy(),target);}}
    private static ChestBlockEntity physical(ServerLevel level,Chest chest){loaded(level,chest.before.pos);if(level.getBlockState(chest.before.pos)!=chest.before.state||!(level.getBlockEntity(chest.before.pos) instanceof ChestBlockEntity tile)||!supported(tile))throw new IllegalStateException("Material chest identity changed; recovery retained");return tile;}
    private static boolean supported(net.minecraft.world.level.block.entity.BlockEntity tile){return tile.getClass()==ChestBlockEntity.class||tile.getClass()==TrappedChestBlockEntity.class;}
    private static boolean matches(ServerLevel level,NativeRawCell image){loaded(level,image.pos);return level.getBlockState(image.pos)==image.state&&level.getBlockEntity(image.pos) instanceof ChestBlockEntity chest&&chest.saveWithFullMetadata(level.registryAccess()).equals(image.tile());}
    private static void loaded(ServerLevel level,BlockPos pos){if(level.getChunkSource().getChunkNow(pos.getX()>>4,pos.getZ()>>4)==null)throw new IllegalArgumentException("Load the material chest and boundary first");}
    private static void thread(ServerLevel level){if(!level.getServer().isSameThread())throw new IllegalStateException("Material accounting requires its server thread");}
}
